// Valida y limpia la entrada ANTES de gastar una llamada a la IA.
// Lista blanca de campos: cualquier campo extra se rechaza.
const MAX = { nombre: 100, apellidos: 150, email: 254, consulta: 4000 };
const MIN_CONSULTA = 10;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
// Caracteres de control (salvo tabulador y salto de línea)
const CONTROL_CHARS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

const body = $input.first().json.body ?? {};
const errors = [];
const data = {};

for (const [field, max] of Object.entries(MAX)) {
  const raw = body[field];
  if (typeof raw !== 'string' || !raw.trim()) {
    errors.push(`${field}: obligatorio`);
    continue;
  }
  const value = raw.replace(CONTROL_CHARS, '').trim();
  if (value.length > max) errors.push(`${field}: máximo ${max} caracteres`);
  data[field] = value;
}

if (data.email) {
  data.email = data.email.toLowerCase();
  if (!EMAIL_RE.test(data.email)) errors.push('email: formato no válido');
}
if (data.consulta && data.consulta.length < MIN_CONSULTA) {
  errors.push(`consulta: mínimo ${MIN_CONSULTA} caracteres`);
}

const extra = Object.keys(body).filter((k) => !(k in MAX));
if (extra.length) errors.push(`campos no permitidos: ${extra.join(', ')}`);

return [{ json: { valid: errors.length === 0, errors, data } }];

// La salida de la IA es una entrada NO confiable: se valida contra listas cerradas.
// La IA clasifica, pero el estado final lo decide este código.
const CATEGORIAS = [
  'presupuesto', 'ciberseguridad', 'desarrollo_a_medida', 'inteligencia_artificial',
  'mantenimiento', 'incidencia', 'consulta_general', 'spam',
];
const PRIORIDADES = ['baja', 'media', 'alta', 'urgente'];
const SENTIMIENTOS = ['positivo', 'neutro', 'negativo'];
const UMBRAL_CONFIANZA = 0.7;  // por debajo -> revisión manual
const UMBRAL_SPAM = 0.9;       // solo se descarta spam con mucha seguridad

const cliente = $('Validar entrada').first().json.data;
// Si la llamada a la IA falló, 'output' no existe y todo cae a revisión manual.
const ia = $input.first().json.output ?? {};
const problemas = [];

function elegir(valor, permitidos, porDefecto, campo) {
  if (permitidos.includes(valor)) return valor;
  problemas.push(campo);
  return porDefecto;
}

const categoria = elegir(ia.categoria, CATEGORIAS, 'consulta_general', 'categoria');
const prioridad = elegir(ia.prioridad, PRIORIDADES, 'media', 'prioridad');
const sentimiento = SENTIMIENTOS.includes(ia.sentimiento) ? ia.sentimiento : null;
const resumen = typeof ia.resumen === 'string' ? ia.resumen.trim().slice(0, 300) : null;

let confianza = Number(ia.confianza);
if (!Number.isFinite(confianza) || confianza < 0 || confianza > 1) {
  confianza = null;
  problemas.push('confianza');
}

let estado = 'nuevo';
if (problemas.length > 0 || confianza === null || confianza < UMBRAL_CONFIANZA) {
  estado = 'revision_manual';
} else if (categoria === 'spam' && confianza >= UMBRAL_SPAM) {
  estado = 'descartado';
}

// Solo columnas de la tabla 'tickets': el nodo Postgres las mapea por nombre.
return [{
  json: {
    ...cliente,
    categoria,
    prioridad,
    sentimiento,
    resumen,
    confianza: confianza === null ? null : Math.round(confianza * 100) / 100,
    estado,
  },
}];
